import { useState, useRef, useEffect, useCallback } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

// ✅ FIXED: Port 5000 = Node backend.  3306 is MySQL (not an HTTP server).
const API        = "http://localhost:5000";
const AMOUNT     = "1";
const YOUR_UPI_ID = "arunsekar664@okaxis";
const PAYEE_NAME  = "CollegeEvent";

/* ─────────────────────────────────────────────────────
   MINI COMPONENTS
───────────────────────────────────────────────────── */
const Spinner = () => (
  <>
    <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    <div style={{
      width: 44, height: 44,
      border: "4px solid #e5e7eb",
      borderTop: "4px solid #6366f1",
      borderRadius: "50%",
      animation: "spin 0.8s linear infinite",
      margin: "0 auto 16px",
    }} />
  </>
);

const Badge = ({ score }) => {
  const cfg =
    score >= 80 ? { bg: "#f0fdf4", border: "#86efac", color: "#166534", icon: "✅" }
    : score >= 50 ? { bg: "#fefce8", border: "#fde047", color: "#854d0e", icon: "⚠️" }
    : { bg: "#fef2f2", border: "#fca5a5", color: "#b91c1c", icon: "❌" };

  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      padding: "4px 14px", borderRadius: 20,
      background: cfg.bg, border: `1px solid ${cfg.border}`,
      color: cfg.color, fontSize: 12, fontWeight: 700,
    }}>
      {cfg.icon} Score: {score}/100
    </span>
  );
};

/* ─────────────────────────────────────────────────────
   STEP INDICATOR
───────────────────────────────────────────────────── */
const StepIndicator = ({ current }) => {
  const steps = ["Form", "Pay", "Verify", "Photo", "ID Card"];
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 24 }}>
      {steps.map((label, i) => {
        const num    = i + 1;
        const done   = current > num;
        const active = current === num;
        return (
          <div key={i} style={{ display: "flex", alignItems: "center" }}>
            <div style={{ textAlign: "center" }}>
              <div style={{
                width: 32, height: 32, borderRadius: "50%",
                background: (done || active) ? "#6366f1" : "#e5e7eb",
                color: (done || active) ? "#fff" : "#9ca3af",
                display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: 13, fontWeight: 700, margin: "0 auto 4px",
                transition: "all 0.3s",
                boxShadow: active ? "0 0 0 3px rgba(99,102,241,0.25)" : "none",
              }}>
                {done ? "✓" : num}
              </div>
              <span style={{
                fontSize: 10,
                color: (active || done) ? "#6366f1" : "#9ca3af",
                fontWeight: active ? 700 : 500,
              }}>
                {label}
              </span>
            </div>
            {i < steps.length - 1 && (
              <div style={{
                width: 28, height: 2,
                background: done ? "#6366f1" : "#e5e7eb",
                margin: "0 4px 14px",
                transition: "background 0.3s",
              }} />
            )}
          </div>
        );
      })}
    </div>
  );
};

/* ─────────────────────────────────────────────────────
   UTR STRENGTH INDICATOR
───────────────────────────────────────────────────── */
function getStrength(utr) {
  if (!utr || utr.length < 5) return null;
  const t           = utr.trim().toUpperCase();
  const uniqueRatio = new Set(t.split("")).size / t.length;
  const bankPfx     = ["HDFC","ICIC","SBIN","AXIS","PYTM","YESB","KOTAK","GPAY","NEFT","RTGS","IMPS"];
  const hasPrefix   = bankPfx.some((p) => t.startsWith(p));
  const hasMixed    = /[A-Z]/.test(t) && /\d/.test(t);

  if (uniqueRatio > 0.6 && hasMixed && t.length >= 12) return { label: "Strong", color: "#16a34a", pct: 90 };
  if (hasPrefix || (hasMixed && t.length >= 10))        return { label: "Good",   color: "#2563eb", pct: 65 };
  if (uniqueRatio < 0.25)                               return { label: "Weak",   color: "#dc2626", pct: 20 };
  return { label: "Fair", color: "#d97706", pct: 45 };
}

/* ─────────────────────────────────────────────────────
   CLIENT-SIDE UTR VALIDATION
───────────────────────────────────────────────────── */
function validateUTRClient(utr) {
  const t = utr.trim();
  if (!t)         return { valid: false, msg: "Please enter your UTR / Transaction ID." };
  if (t.length < 10) return { valid: false, msg: "UTR must be at least 10 characters." };
  if (t.length > 22) return { valid: false, msg: "UTR must not exceed 22 characters." };
  if (!/^[a-zA-Z0-9]+$/.test(t)) return { valid: false, msg: "Only letters and numbers. No spaces or symbols." };
  if (/^(.)\1+$/.test(t))        return { valid: false, msg: "❌ Repeated characters — looks fake." };
  if ("01234567890123456789012345".includes(t)) return { valid: false, msg: "❌ Sequential digits are not valid." };
  for (const p of [/^test/i, /^fake/i, /^dummy/i, /^sample/i, /^1234/, /^0000/, /^9999/]) {
    if (p.test(t)) return { valid: false, msg: "❌ Invalid UTR — enter the real one from your payment app." };
  }
  return { valid: true };
}

/* ─────────────────────────────────────────────────────
   FORM FIELD COMPONENT
   Defined OUTSIDE Register so React never remounts
   inputs on re-render (fixes the single-letter-then-
   lose-focus bug).
───────────────────────────────────────────────────── */
const FormField = ({ label, name, type, placeholder, value, onChange, onBlur, error, aiResult, loading }) => (
  <div style={{ marginBottom: 10 }}>
    <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#374151", marginBottom: 5 }}>
      {label}
    </label>
    <div style={{ position: "relative" }}>
      <input
        style={{
          width: "100%", padding: "11px 13px", fontSize: 14,
          borderRadius: 9, border: `1.5px solid ${error ? "#f87171" : "#d1d5db"}`,
          marginBottom: 4, boxSizing: "border-box", background: "#fafafa",
          outline: "none", transition: "border-color 0.2s",
          paddingRight: loading ? 36 : 13,
        }}
        name={name}
        type={type || "text"}
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        autoComplete="off"
      />
      {loading && (
        <span style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", fontSize: 14 }}>
          🔄
        </span>
      )}
    </div>
    {error && <p style={{ fontSize: 11, color: "#dc2626", marginBottom: 8 }}>⚠️ {error}</p>}
    {aiResult?.valid && !error && (
      <p style={{ fontSize: 11, color: "#16a34a", marginBottom: 6 }}>✅ {aiResult.reason}</p>
    )}
  </div>
);

/* ═══════════════════════════════════════════════════
   MAIN COMPONENT
═══════════════════════════════════════════════════ */
export default function Register() {
  const location  = useLocation();
  const eventId   = location.state?.eventId   || "";
  const eventName = location.state?.eventName || "No Event Selected";

  /* ── form state ── */
  const [formData,     setFormData]     = useState({ name: "", college_name: "", phone: "", email: "", event_id: eventId });
  const [fieldErrors,  setFieldErrors]  = useState({});
  const [fieldAI,      setFieldAI]      = useState({});
  const [fieldLoading, setFieldLoading] = useState({});

  /* ── step & registration ── */
  const [step,         setStep]         = useState(1);
  const [userId,       setUserId]       = useState("");
  const [qrData,       setQrData]       = useState("");
  const [photo,        setPhoto]        = useState("");
  const [autoApproved, setAutoApproved] = useState(false);

  /* ── UTR ── */
  const [utrNumber,    setUtrNumber]    = useState("");
  const [utrError,     setUtrError]     = useState("");
  const [utrScore,     setUtrScore]     = useState(null);
  const [utrAIResult,  setUtrAIResult]  = useState(null);
  const [utrAILoading, setUtrAILoading] = useState(false);
  const [submitting,   setSubmitting]   = useState(false);

  /* ── polling ── */
  const [polling,    setPolling]    = useState(false);
  const [pollStatus, setPollStatus] = useState("");

  /* ── screenshot ── */
  const [paymentScreenshot,   setPaymentScreenshot]   = useState(null);
  const [screenshotPreview,   setScreenshotPreview]   = useState("");
  const [screenshotError,     setScreenshotError]     = useState("");
  const [screenshotAIResult,  setScreenshotAIResult]  = useState(null);
  const [screenshotAnalyzing, setScreenshotAnalyzing] = useState(false);

  /* ── refs ── */
  const videoRef           = useRef(null);
  const canvasRef          = useRef(null);
  const idCardRef          = useRef(null);
  const streamRef          = useRef(null);
  const pollRef            = useRef(null);
  const screenshotInputRef = useRef(null);
  const utrDebounceRef     = useRef(null);

  const upiQRValue = `upi://pay?pa=${YOUR_UPI_ID}&pn=${encodeURIComponent(PAYEE_NAME)}&am=${AMOUNT}&cu=INR`;

  // Clear polling interval on unmount
  useEffect(() => () => { if (pollRef.current) clearInterval(pollRef.current); }, []);

  /* ─────────────────────────────────────────────────
     FORM FIELD HANDLERS
     handleChange  → updates state only (no AI call mid-typing)
     validateFieldAI + handleBlur → AI fires when user leaves field
  ───────────────────────────────────────────────── */
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // Clear error as user types — never re-validate mid-typing
    setFieldErrors((prev) => ({ ...prev, [name]: "" }));
  };

  const validateFieldAI = useCallback(async (field, value) => {
    if (!value || value.trim().length < 2) return;
    setFieldLoading((prev) => ({ ...prev, [field]: true }));
    try {
      const resp = await axios.post(`${API}/api/validate-field`, { field, value });
      if (resp.data?.success) {
        setFieldAI((prev) => ({ ...prev, [field]: resp.data }));
        if (!resp.data.valid) {
          setFieldErrors((prev) => ({ ...prev, [field]: resp.data.reason }));
        }
      }
    } catch { /* AI unavailable — silently ignore, don't block the user */ }
    finally {
      setFieldLoading((prev) => ({ ...prev, [field]: false }));
    }
  }, []);

  // ✅ FIXED: handleBlur is now wired to FormField's onBlur prop (was declared but never used before)
  const handleBlur = useCallback((e) => {
    const { name, value } = e.target;
    validateFieldAI(name, value);
  }, [validateFieldAI]);

  /* ─────────────────────────────────────────────────
     UTR LIVE AI ANALYSIS  (debounced 1.2 s)
     Calls Node proxy (/api/analyze-utr) → Python AI
     so CORS is never an issue from the browser.
  ───────────────────────────────────────────────── */
  const analyzeUTRLive = useCallback(async (utr) => {
    if (!utr || utr.trim().length < 10) { setUtrAIResult(null); return; }
    const check = validateUTRClient(utr);
    if (!check.valid) { setUtrAIResult(null); return; }

    setUtrAILoading(true);
    try {
      const res = await axios.post(`${API}/api/analyze-utr`, {
        utr: utr.trim(),
        user: { name: formData.name, email: formData.email },
      });
      if (res.data?.success) setUtrAIResult(res.data);
    } catch {
      setUtrAIResult(null);
    } finally {
      setUtrAILoading(false);
    }
  }, [formData.name, formData.email]);

  const handleUTRChange = (e) => {
    const v = e.target.value.replace(/\s/g, "").slice(0, 22);
    setUtrNumber(v);
    setUtrError("");
    setUtrAIResult(null);
    clearTimeout(utrDebounceRef.current);
    utrDebounceRef.current = setTimeout(() => analyzeUTRLive(v), 1200);
  };

  /* ─────────────────────────────────────────────────
     SCREENSHOT HANDLER
     Calls Node proxy (/api/analyze-screenshot) → Python AI
  ───────────────────────────────────────────────── */
  const handleScreenshotChange = async (input) => {
    setScreenshotError("");
    const file = input?.target ? input.target.files?.[0] : input;
    if (!file?.type) return;

    const allowed = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    if (!allowed.includes(file.type)) { setScreenshotError("Only JPG, PNG, or WEBP allowed."); return; }
    if (file.size > 5 * 1024 * 1024)  { setScreenshotError("File must be under 5 MB."); return; }

    const reader = new FileReader();
    reader.onloadend = async () => {
      const b64 = reader.result;
      setPaymentScreenshot(b64);
      setScreenshotPreview(b64);
      setScreenshotAIResult(null);
      setScreenshotAnalyzing(true);
      try {
        const res = await axios.post(`${API}/api/analyze-screenshot`, {
          imageBase64: b64,
          utr: utrNumber,
          amount: AMOUNT,
        });
        setScreenshotAIResult(res.data);
      } catch {
        setScreenshotAIResult({
          is_genuine: null,
          summary: "Could not reach AI service. Admin will verify manually.",
          confidence: 0,
        });
      } finally {
        setScreenshotAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const removeScreenshot = () => {
    setPaymentScreenshot(null);
    setScreenshotPreview("");
    setScreenshotError("");
    setScreenshotAIResult(null);
    if (screenshotInputRef.current) screenshotInputRef.current.value = "";
  };

  /* ─────────────────────────────────────────────────
     STEP 1 → 2  (form validation)
  ───────────────────────────────────────────────── */
  const handleShowPayment = (e) => {
    e.preventDefault();
    const errs = {};
    if (!formData.name.trim())                     errs.name         = "Name is required.";
    if (!formData.college_name.trim())             errs.college_name = "College name is required.";
    if (!/^\d{10}$/.test(formData.phone))          errs.phone        = "Enter a valid 10-digit phone number.";
    if (!/\S+@\S+\.\S+/.test(formData.email))      errs.email        = "Enter a valid email address.";
    if (Object.keys(errs).length) { setFieldErrors(errs); return; }
    setStep(2);
    setUtrError("");
  };

  /* ─────────────────────────────────────────────────
     SUBMIT UTR
  ───────────────────────────────────────────────── */
  const submitUTR = async () => {
    setUtrError("");
    const check = validateUTRClient(utrNumber);
    if (!check.valid) { setUtrError(check.msg); return; }

    if (utrAIResult?.block) {
      setUtrError(`❌ AI flagged this UTR: ${utrAIResult.ai_summary || utrAIResult.flags?.[0] || "Fake UTR detected"}`);
      return;
    }

    setSubmitting(true);
    try {
      const res = await axios.post(`${API}/submit-utr`, {
        utrNumber: utrNumber.trim(),
        amount: AMOUNT,
        ...formData,
        photo,
        paymentScreenshot,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        setUtrScore(res.data.utrScore);
        if (res.data.autoApproved) {
          setAutoApproved(true);
          setStep(4);
        } else {
          setStep(3);
          startPolling(res.data.userId);
        }
      } else {
        setUtrError(res.data.message || "Submission failed. Please try again.");
      }
    } catch {
      setUtrError("Server error. Make sure backend is running on port 5000.");
    } finally {
      setSubmitting(false);
    }
  };

  /* ─────────────────────────────────────────────────
     POLLING
  ───────────────────────────────────────────────── */
  const startPolling = (uid) => {
    setPolling(true);
    setPollStatus("⏳ Waiting for admin to verify your payment...");
    pollRef.current = setInterval(async () => {
      try {
        const res = await axios.get(`${API}/user-status/${uid}`);
        if (res.data.success) {
          if (res.data.payment_status === "approved") {
            clearInterval(pollRef.current);
            setPolling(false);
            setPollStatus("✅ Payment Verified!");
            setTimeout(() => setStep(4), 800);
          } else if (res.data.payment_status === "rejected") {
            clearInterval(pollRef.current);
            setPolling(false);
            setPollStatus("❌ Payment rejected. Please contact support.");
          } else {
            setPollStatus("⏳ Admin is reviewing... please wait.");
          }
        }
      } catch {
        setPollStatus("⚠️ Checking status...");
      }
    }, 5000);
  };

  /* ─────────────────────────────────────────────────
     CAMERA
  ───────────────────────────────────────────────── */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current        = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied. Please allow camera permissions.");
    }
  };

  const capturePhoto = () => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width  = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    setPhoto(canvas.toDataURL("image/png"));
    if (streamRef.current) streamRef.current.getTracks().forEach((t) => t.stop());
    setStep(5);
  };

  const skipPhoto = () => { setPhoto(""); setStep(5); };

  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link      = document.createElement("a");
      link.download   = "Event_ID_Card.png";
      link.href       = canvas.toDataURL();
      link.click();
    });
  };

  const strength = getStrength(utrNumber);

  /* ─────────────────────────────────────────────────
     SHARED STYLES
  ───────────────────────────────────────────────── */
  const S = {
    page:    { minHeight: "100vh", background: "#f1f5f9" },
    wrap:    { maxWidth: 500, margin: "0 auto", padding: "24px 16px" },
    card:    { background: "#fff", borderRadius: 16, padding: "22px 20px", marginBottom: 14, boxShadow: "0 1px 6px rgba(0,0,0,0.07)" },
    title:   { fontSize: 22, fontWeight: 800, color: "#111827", marginBottom: 4 },
    sub:     { fontSize: 13, color: "#6b7280", marginBottom: 20 },
    label:   { display: "block", fontSize: 13, fontWeight: 600, color: "#374151", marginBottom: 5 },
    hint:    { fontSize: 11, color: "#9ca3af", marginBottom: 10 },
    input:   (err) => ({
      width: "100%", padding: "11px 13px", fontSize: 14,
      borderRadius: 9, border: `1.5px solid ${err ? "#f87171" : "#d1d5db"}`,
      marginBottom: 4, boxSizing: "border-box", background: "#fafafa",
      outline: "none", transition: "border-color 0.2s",
    }),
    errText:  { fontSize: 11, color: "#dc2626", marginBottom: 8 },
    btn:      (color) => ({ width: "100%", padding: "13px", background: color, color: "#fff", border: "none", borderRadius: 10, fontSize: 14, fontWeight: 700, cursor: "pointer", marginTop: 8 }),
    disBtn:   { width: "100%", padding: "13px", background: "#9ca3af", color: "#fff", border: "none", borderRadius: 10, fontSize: 14, fontWeight: 700, cursor: "not-allowed", marginTop: 8 },
    infoBox:  { background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 9, padding: "10px 13px", fontSize: 13, color: "#1e40af", marginBottom: 14 },
    warnBox:  { background: "#fefce8", border: "1px solid #fde047", borderRadius: 9, padding: "10px 13px", fontSize: 13, color: "#854d0e", marginBottom: 14 },
    errBox:   { background: "#fef2f2", border: "1px solid #fca5a5", borderRadius: 9, padding: "10px 13px", fontSize: 13, color: "#b91c1c", marginBottom: 12 },
    okBox:    { background: "#f0fdf4", border: "1px solid #86efac", borderRadius: 9, padding: "10px 13px", fontSize: 13, color: "#166534", marginBottom: 14 },
    backBtn:  { background: "none", border: "none", color: "#6b7280", cursor: "pointer", textDecoration: "underline", fontSize: 13, margin: "10px auto 0", display: "block", textAlign: "center" },
    qrWrap:   { display: "flex", flexDirection: "column", alignItems: "center", background: "#f9fafb", border: "1px solid #e5e7eb", borderRadius: 12, padding: 18, marginBottom: 14 },
    idCard:   { border: "2px solid #6366f1", width: 300, margin: "0 auto", padding: 20, borderRadius: 16, background: "#fff", boxShadow: "0 4px 16px rgba(99,102,241,0.15)" },
  };

  /* ═══════════════════════════════════════════════
     RENDER
  ═══════════════════════════════════════════════ */
  return (
    <div style={S.page}>
      <Navbar />
      <div style={S.wrap}>
        <h2 style={S.title}>Event Registration</h2>
        <p style={S.sub}>
          Fill the form and pay ₹{AMOUNT} to register for{" "}
          <strong style={{ color: "#6366f1" }}>{eventName}</strong>
        </p>

        <StepIndicator current={step} />

        {/* ══ STEP 1: FORM ══ */}
        {step === 1 && (
          <form onSubmit={handleShowPayment}>
            <div style={S.card}>
              <FormField
                label="Full Name" name="name" placeholder="e.g. Arun Sekar"
                value={formData.name} onChange={handleChange} onBlur={handleBlur}
                error={fieldErrors.name} aiResult={fieldAI.name} loading={fieldLoading.name}
              />
              <FormField
                label="College Name" name="college_name" placeholder="e.g. Anna University"
                value={formData.college_name} onChange={handleChange} onBlur={handleBlur}
                error={fieldErrors.college_name} aiResult={fieldAI.college_name} loading={fieldLoading.college_name}
              />
              <FormField
                label="Phone Number" name="phone" type="tel" placeholder="10-digit mobile number"
                value={formData.phone} onChange={handleChange} onBlur={handleBlur}
                error={fieldErrors.phone} aiResult={fieldAI.phone} loading={fieldLoading.phone}
              />
              <FormField
                label="Email Address" name="email" type="email" placeholder="you@example.com"
                value={formData.email} onChange={handleChange} onBlur={handleBlur}
                error={fieldErrors.email} aiResult={fieldAI.email} loading={fieldLoading.email}
              />
              <div style={S.okBox}>🎫 Selected Event: <strong>{eventName}</strong></div>
              <p style={{ fontSize: 11, color: "#9ca3af", marginBottom: 8 }}>
                🤖 AI validates fields when you leave each box.
              </p>
              <button type="submit" style={S.btn("#6366f1")}>Proceed to Pay ₹{AMOUNT} →</button>
            </div>
          </form>
        )}

        {/* ══ STEP 2: PAYMENT + SCREENSHOT + UTR ══ */}
        {step === 2 && (
          <>
            {/* QR card */}
            <div style={S.card}>
              <label style={{ ...S.label, fontSize: 15 }}>Scan QR &amp; Pay ₹{AMOUNT}</label>
              <p style={S.hint}>Open GPay / PhonePe / Paytm → Scan → Pay ₹{AMOUNT}</p>
              <div style={S.qrWrap}>
                <div style={{ padding: 12, background: "#fff", borderRadius: 10, border: "1px solid #e5e7eb" }}>
                  <QRCode value={upiQRValue} size={180} />
                </div>
                <p style={{ marginTop: 10, fontSize: 12, color: "#6b7280" }}>
                  UPI: <strong style={{ color: "#111" }}>{YOUR_UPI_ID}</strong>
                </p>
              </div>
              <div style={S.infoBox}>
                <strong>Steps:</strong> Open app → Scan QR → Pay → Copy the{" "}
                <strong>UTR / Transaction ID</strong> shown on the success screen.
              </div>
            </div>

            {/* Screenshot card */}
            <div style={S.card}>
              <label style={{ ...S.label, fontSize: 14 }}>
                📷 Upload Payment Screenshot{" "}
                <span style={{ fontWeight: 400, color: "#9ca3af" }}>(speeds up verification)</span>
              </label>
              <p style={S.hint}>AI auto-verifies your screenshot instantly — no admin wait needed.</p>

              {screenshotError && <div style={S.errBox}>⚠️ {screenshotError}</div>}

              {screenshotPreview ? (
                <div style={{ position: "relative", marginBottom: 12, borderRadius: 10, overflow: "hidden", border: "1px solid #e5e7eb" }}>
                  <img
                    src={screenshotPreview}
                    alt="Payment screenshot"
                    style={{ width: "100%", maxHeight: 200, objectFit: "cover", display: "block" }}
                  />
                  <button
                    onClick={removeScreenshot}
                    style={{
                      position: "absolute", top: 8, right: 8,
                      background: "#ef4444", color: "#fff", border: "none",
                      borderRadius: "50%", width: 26, height: 26,
                      cursor: "pointer", fontWeight: 700, fontSize: 13,
                    }}
                  >
                    ✕
                  </button>

                  {screenshotAnalyzing && (
                    <div style={{ background: "#eff6ff", padding: "8px 12px", fontSize: 12, color: "#1e40af" }}>
                      🤖 AI is analyzing your screenshot...
                    </div>
                  )}

                  {screenshotAIResult && !screenshotAnalyzing && (
                    <div style={{
                      background:   screenshotAIResult.is_genuine ? "#f0fdf4" : screenshotAIResult.is_genuine === false ? "#fef2f2" : "#fefce8",
                      borderTop:   `1px solid ${screenshotAIResult.is_genuine ? "#86efac" : screenshotAIResult.is_genuine === false ? "#fca5a5" : "#fde047"}`,
                      padding: "8px 12px", fontSize: 12,
                      color: screenshotAIResult.is_genuine ? "#166534" : screenshotAIResult.is_genuine === false ? "#b91c1c" : "#854d0e",
                    }}>
                      {screenshotAIResult.is_genuine === true
                        ? `✅ AI verified: Genuine ${screenshotAIResult.app_detected || "UPI"} payment (${screenshotAIResult.confidence || 0}% confidence)`
                        : screenshotAIResult.manipulation_detected
                        ? "❌ AI: Screenshot manipulation detected"
                        : `⚠️ ${screenshotAIResult.summary || "Admin will verify manually."}`}
                    </div>
                  )}
                </div>
              ) : (
                <div
                  style={{ border: "2px dashed #d1d5db", borderRadius: 10, padding: "20px 14px", textAlign: "center", cursor: "pointer", background: "#f9fafb", marginBottom: 12 }}
                  onClick={() => screenshotInputRef.current?.click()}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => { e.preventDefault(); handleScreenshotChange(e.dataTransfer.files[0]); }}
                >
                  <div style={{ fontSize: 30, marginBottom: 6 }}>📲</div>
                  <p style={{ fontSize: 13, color: "#6b7280", marginBottom: 4 }}>
                    <strong style={{ color: "#6366f1" }}>Click to upload</strong> or drag &amp; drop
                  </p>
                  <p style={{ fontSize: 11, color: "#9ca3af" }}>JPG / PNG / WEBP · max 5 MB</p>
                </div>
              )}
              <input
                ref={screenshotInputRef}
                type="file"
                accept="image/jpeg,image/jpg,image/png,image/webp"
                onChange={(e) => handleScreenshotChange(e.target.files[0])}
                style={{ display: "none" }}
              />
            </div>

            {/* UTR card */}
            <div style={S.card}>
              <label style={S.label}>Transaction ID / UTR</label>
              <p style={S.hint}>GPay → UPI Ref No &nbsp;|&nbsp; PhonePe → Transaction ID &nbsp;|&nbsp; Paytm → UTR</p>

              <div style={S.warnBox}>
                ⚠️ <strong>Important:</strong> Our AI analyzes UTR authenticity in real time.
                Fake submissions are automatically <strong>blocked &amp; reported</strong>.
              </div>

              {utrError && <div style={S.errBox}>⚠️ {utrError}</div>}

              <input
                type="text"
                placeholder="e.g. HDFC2025ABCD1234 or 123456789012"
                value={utrNumber}
                onChange={handleUTRChange}
                style={{ ...S.input(utrError), letterSpacing: "1px", fontFamily: "monospace", fontSize: 15, marginBottom: 8 }}
              />

              {/* Strength bar */}
              {strength && (
                <div style={{ marginBottom: 12 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                    <span style={{ fontSize: 11, color: "#6b7280" }}>UTR Strength</span>
                    <span style={{ fontSize: 11, fontWeight: 700, color: strength.color }}>{strength.label}</span>
                  </div>
                  <div style={{ height: 5, background: "#e5e7eb", borderRadius: 4 }}>
                    <div style={{ height: 5, width: `${strength.pct}%`, background: strength.color, borderRadius: 4, transition: "width 0.4s" }} />
                  </div>
                </div>
              )}

              {/* Live AI result */}
              {utrAILoading && (
                <div style={{ ...S.infoBox, display: "flex", alignItems: "center", gap: 8 }}>
                  <span>🤖</span><span>AI analyzing UTR...</span>
                </div>
              )}

              {utrAIResult && !utrAILoading && (
                <div style={{
                  background:    utrAIResult.verdict === "likely_real" ? "#f0fdf4" : utrAIResult.verdict === "suspicious" ? "#fefce8" : "#fef2f2",
                  border:       `1px solid ${utrAIResult.verdict === "likely_real" ? "#86efac" : utrAIResult.verdict === "suspicious" ? "#fde047" : "#fca5a5"}`,
                  borderRadius: 9, padding: "10px 13px", fontSize: 12, marginBottom: 12,
                }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                    <span style={{ fontWeight: 700 }}>
                      🤖 AI Analysis{" "}
                      <span style={{ fontWeight: 400, color: "#6b7280" }}>
                        ({utrAIResult.source === "claude_ai" ? "Claude AI" : "Rule Engine"})
                      </span>
                    </span>
                    <Badge score={utrAIResult.score} />
                  </div>
                  {utrAIResult.ai_summary && (
                    <p style={{ color: "#374151", marginBottom: 6 }}>{utrAIResult.ai_summary}</p>
                  )}
                  {utrAIResult.flags?.length > 0 && (
                    <ul style={{ margin: 0, paddingLeft: 16 }}>
                      {utrAIResult.flags.map((f, i) => (
                        <li key={i} style={{ fontSize: 11, color: "#374151", marginBottom: 2 }}>{f}</li>
                      ))}
                    </ul>
                  )}
                </div>
              )}

              {/* Submit button */}
              {submitting ? (
                <button disabled style={S.disBtn}>🔬 Verifying with AI...</button>
              ) : utrNumber.trim().length < 10 ? (
                <button disabled style={S.disBtn}>Enter UTR to Continue</button>
              ) : utrAIResult?.block ? (
                <button disabled style={{ ...S.disBtn, background: "#dc2626" }}>❌ UTR Blocked by AI</button>
              ) : (
                <button onClick={submitUTR} style={S.btn("#16a34a")}>✅ Submit UTR for Verification</button>
              )}
            </div>

            <button
              onClick={() => { setStep(1); setUtrNumber(""); setUtrError(""); setUtrAIResult(null); }}
              style={S.backBtn}
            >
              ← Back to Form
            </button>
          </>
        )}

        {/* ══ STEP 3: WAITING FOR ADMIN ══ */}
        {step === 3 && (
          <div style={{ ...S.card, textAlign: "center", padding: "28px 20px" }}>
            {polling && <Spinner />}
            <h3 style={{ color: "#6366f1", marginBottom: 8 }}>UTR Submitted!</h3>
            <p style={{ color: "#6b7280", fontSize: 14, marginBottom: 14 }}>
              Your UTR <strong style={{ fontFamily: "monospace", color: "#111" }}>{utrNumber}</strong> is under review.
            </p>
            {utrScore !== null && <div style={{ marginBottom: 14 }}><Badge score={utrScore} /></div>}
            <div style={{ ...S.infoBox, textAlign: "center" }}>{pollStatus}</div>
            <div style={{ ...S.warnBox, textAlign: "left" }}>
              <strong>What happens next:</strong><br />
              1. Admin checks your payment<br />
              2. Genuine → <strong>Approved ✅</strong> (auto-advances)<br />
              3. Fake → <strong>Rejected ❌</strong><br />
              4. Refreshes every 5 seconds — <em>do not close</em>
            </div>
            <p style={{ fontSize: 11, color: "#9ca3af" }}>User ID: <strong>#{userId}</strong></p>
          </div>
        )}

        {/* ══ STEP 4: CAMERA ══ */}
        {step === 4 && (
          <div style={S.card}>
            {autoApproved
              ? <div style={S.okBox}>✅ Payment auto-verified by AI! Take your photo for the ID card.</div>
              : <div style={S.okBox}>✅ Payment verified by admin! Take your photo for the ID card.</div>
            }
            <p style={{ ...S.label, fontSize: 15, marginBottom: 12 }}>Your Registration QR</p>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
              <QRCode value={qrData.toString()} size={180} />
            </div>
            <button onClick={openCamera}   style={S.btn("#6366f1")}>📷 Open Camera</button>
            <video
              ref={videoRef}
              width="100%"
              style={{ borderRadius: 8, border: "1px solid #e5e7eb", marginTop: 12, display: "block" }}
            />
            <button onClick={capturePhoto} style={S.btn("#0891b2")}>Capture Photo</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
            <button onClick={skipPhoto}    style={S.backBtn}>Skip photo → Go to ID Card</button>
          </div>
        )}

        {/* ══ STEP 5: ID CARD ══ */}
        {step === 5 && (
          <div>
            <p style={{ ...S.label, fontSize: 15, textAlign: "center", marginBottom: 14 }}>🪪 Your Event ID Card</p>
            <div ref={idCardRef} style={S.idCard}>
              <div style={{ background: "linear-gradient(135deg,#6366f1,#818cf8)", margin: "-20px -20px 16px", padding: "14px 20px", borderRadius: "14px 14px 0 0" }}>
                <h3 style={{ color: "#fff", margin: 0, fontSize: 15 }}>🎫 College Event</h3>
                <p style={{ color: "rgba(255,255,255,0.8)", margin: "2px 0 0", fontSize: 11 }}>Official ID Card</p>
              </div>
              <p style={{ fontSize: 14, marginBottom: 6 }}><strong>Name:</strong>    {formData.name}</p>
              <p style={{ fontSize: 14, marginBottom: 6 }}><strong>College:</strong> {formData.college_name}</p>
              <p style={{ fontSize: 14, marginBottom: 6 }}><strong>User ID:</strong> #{userId}</p>
              <p style={{ fontSize: 14, marginBottom: 14 }}><strong>Event:</strong>   {eventName}</p>
              <div style={{ display: "flex", justifyContent: "center", marginBottom: 14 }}>
                <QRCode value={qrData.toString()} size={110} />
              </div>
              {photo ? (
                <div style={{ display: "flex", justifyContent: "center" }}>
                  <img src={photo} alt="User" width="100" style={{ borderRadius: 8, border: "2px solid #e5e7eb" }} />
                </div>
              ) : (
                <div style={{ width: 100, height: 100, background: "#f3f4f6", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto", fontSize: 32, border: "2px solid #e5e7eb" }}>
                  👤
                </div>
              )}
            </div>
            <button onClick={downloadCard} style={{ ...S.btn("#16a34a"), marginTop: 16 }}>⬇️ Download ID Card</button>
            <p style={{ fontSize: 11, color: "#9ca3af", textAlign: "center", marginTop: 8 }}>
              Your registration is saved even if you don't download. User ID: #{userId}
            </p>
          </div>
        )}

      </div>
    </div>
  );
}
